const { RoomRegistry } = require("./rooms");

const registry = new RoomRegistry();
const out = [];
const lines = require("fs").readFileSync(0, "utf8").split("\n");
for (const raw of lines) {
  const p = raw.trim().split(/\s+/).filter(Boolean);
  if (p.length === 0) continue;
  if (p[0] === "ROOM" && p.length === 3 && /^\d+$/.test(p[1]) && /^[1-9]\d*$/.test(p[2])) out.push(registry.addRoom(Number(p[1]), Number(p[2])));
  else if (p[0] === "ALLOT" && p.length === 2) out.push(registry.allot(p[1]));
  else if (p[0] === "VACATE" && p.length === 2) out.push(registry.vacate(p[1]));
  else if (p[0] === "SHOW" && p.length === 1) {
    const rows = registry.show();
    out.push(rows.length ? rows.join("\n") : "no rooms");
  } else out.push(`error: bad command ${raw.trim()}`);
}
console.log(out.join("\n"));

