class RoomRegistry {
  constructor() {
    this.rooms = new Map();    // room number -> { beds, students: Set }
    this.whereIs = new Map();  // student -> room number
  }

  addRoom(no, beds) {
    if (this.rooms.has(no)) return `error: room ${no} exists`;
    this.rooms.set(no, { beds, students: new Set() });
    return `room ${no} added with ${beds} beds`;
  }

  allot(student) {
    if (this.whereIs.has(student)) return `error: ${student} already in room ${this.whereIs.get(student)}`;
    const numbers = [...this.rooms.keys()].sort((a, b) => a - b);
    for (const no of numbers) {
      const room = this.rooms.get(no);
      if (room.students.size < room.beds) {
        room.students.add(student);
        this.whereIs.set(student, no);
        return `${student} -> room ${no}`;
      }
    }
    return "error: hostel full";
  }

  vacate(student) {
    const no = this.whereIs.get(student);
    if (no === undefined) return `error: ${student} not found`;
    this.rooms.get(no).students.delete(student);
    this.whereIs.delete(student);
    return `${student} left room ${no}`;
  }

  show() {
    return [...this.rooms.keys()]
      .sort((a, b) => a - b)
      .map((no) => {
        const room = this.rooms.get(no);
        const names = [...room.students].sort().join(", ") || "-";
        return `room ${no}: ${names} (${room.beds - room.students.size} free)`;
      });
  }
}

module.exports = { RoomRegistry };
